INSERT INTO `tmp_ruru_quest_template_locale` (`ID`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`PortraitGiverText`,`PortraitGiverName`,`PortraitTurnInText`,`PortraitTurnInName`,`QuestCompletionLog`) VALUES
(5,'Урчащий живот Трясунчика','Поговорите с шеф-поваром Груалем.','Я прячусь в этом призрачном городе несколько недель и не ел ничего, кроме трав и кореньев! Страшно хочется нормальной еды, и я за нее хорошо заплачу.$B$BУстрой мне пир, и не пожалеешь.$B$BГоворят, что шеф-повар Груаль в таверне "Алый ворон" делает превосходные темные пирожки с крабами...','','','','','',''),
(14,'Народное ополчение','Убейте 15 разбойников, 5 налетчиков и 5 кастетчиков из Братства Справедливости. Вернитесь к Гриану Камнегриву на Сторожевой Холм.','Некоторые члены Братства Справедливости от нас ускользнули. Один из моих разведчиков, которому я очень доверяю, сообщает, что члены этого братства грабят и разоряют деревни вплоть до Южного Западного Края. Мы считаем, что они скрываются в Холмах Разбойничьих Кинжалов, замышляя новые бесчинства. Убей этих негодяев от имени народного ополчения.','','','','','',''),
(55,'Морбент Скверн','Примените Проклятье Морбента против Морбента Скверна, убейте его и верните Проклятье Морбента в лагерь Свена.','Морбент Скверн прячется в своем доме на вершине холма на востоке, рядом с кладбищем Вороньего холма. Пора положить конец его бесчинствам в наших землях…$B$BПримени против него Проклятье Морбента, оно обратит в прах всю его защитную магию.$b$bУбей его. Убей негодяя и избавь нас от его гнусных козней. Стань орудием возмездия, $Gгерой:героиня; Сумеречного леса.','','','','','',''),
(66,'Легенда о Сталване','Найдите клерка Далтри в ратуше Темнолесья.','Вчера ночью меня охватил беспричинный ужас. Я почувствовала, что моя внучка Алисса оказалась в страшной опасности. Я разложила карты... и со стола на меня взглянула Смерть.$B$BПогрузившись в длительный и тяжкий транс, я сумела разгадать эту темную тайну. Мне открылось имя: Сталван.$B$BОтыщи клерка в городской Ратуше и постарайся побольше разузнать об этом Сталване. Я опасаюсь за всех нас.','','','','','',''),
(67,'Легенда о Сталване','Отправьтесь в Лунореченскую школу и сообщите все сведения о Сталване клерку Далтри.','Сталван, значит? Дай-ка погляжу в журнал.$b$BСталван... Сталван... Ну-ка... А, вот он! У меня есть запись о некоем господине Сталване Мистмантле. Последний адрес – Лунореченская школа. Но это было так давно!$b$bОкажи любезность, дай знать, если выяснишь что-либо об этом типе. Записи должны содержаться в порядке.','','','','','',''),
(68,'Легенда о Сталване','Отнесите пыльное неотосланное письмо клерку Далтри.','Вы находите в старом сундуке пыльное неотосланное письмо.','','','','','',''),
(70,'Легенда о Сталване','Возьмите недоставленное письмо Сталвана из сундука и доставьте его в район каналов Штормграда.','Имя Сталван мне знакомо. А, вспомнил.$b$bМного лет назад ненастной ночью в трактир явился гонец, искавший убежища от непогоды. Около полуночи этот человек, бледный от страха, сбежал вниз по лестнице в пижаме и исчез.$b$bВторопях он оставил письма в сундуке на втором этаже. За ними он так и не вернулся. Осталось одно, от этого Сталвана. Адресовано оно в район каналов Штормграда. Можешь прочитать.','','','','','',''),
(72,'Легенда о Сталване','Найдите улики в пожитках управляющего Фольсома.','Мой отец был сторожем в этом поместье задолго до меня. Ему-то и пришлось вытирать кровь после того убийства. Но это к делу не относится.$b$bПоследние деньги треста Кременника давно иссякли. А теперь и последние семейные ценности отправляются прямиком на аукцион. Проклятые сборщики налогов!.. Пожалуй, если ты хочешь узнать побольше, можешь порыться в этом барахле. Кто знает, что тебе попадется.','','','','','',''),
(90,'Пряные котлеты из волчатины','Раздобудьте 10 постных волчьих боков и возвращайтесь к шеф-повару Груалю в Темнолесье.','Мое коронное блюдо – пряные котлеты из волчатины! Разумеется, я могу тебе их пожарить, но для этого мне понадобятся кое-какие продукты. Раздобудь 10 постных волчьих боков. В лесу волков полно, и добыть мясо будет несложно. Кстати, тебе еще повезло – буквально на днях мне пришел очередной груз травяных приправ Штормграда, так что от тебя мне понадобится только сама волчатина.','','','','','',''),
(119,'Доставка подков','Вернитесь к Вернеру Осгуду в Красногорье. Отдайте ему ящик с подковами.','Ладно, так и быть, пошлю ему 50 подков…$B$BВот они, уже упакованы, осталось только доставить! Передай Вернеру, что с ним приятно иметь дело. Пусть не забудет прочитать записку, прикрепленную к ящику!','','','','','',''),
(133,'Фигурка вурдалака','Добудьте 7 ребер вурдалаков и принесите их в хижину Аберкромби.','Я живу вдали от города, никто меня не защищает, и даже странно, как это меня до сих пор не сожрали вурдалаки и мертвяки! Только вчера несколько костеглодов ломились ко мне в дом!..$B$BЯ хочу сделать особую фигурку – что-то вроде пугала для этой нежити. Для этого мне понадобится несколько ребер вурдалаков. Их можно добыть, убивая плотоядов, костеглодов, мозгоедов, гнилую нежить и распространителей чумы.$B$BПринеси мне ребра, и я дам тебе несколько монет.','','','','','',''),
(134,'Нападение огров','Вернуть ящик Аберкромби владельцу.','Несколько недель назад я собирал травы вдали от дома, и на меня напал отряд огров! Я сбежал, бросив свой ящик с ценными инструментами и травами.$B$BПрогнав меня, они вернулись к своему кургану в южной части Сумеречного леса. Думаю, они оставили мой ящик неподалеку от кургана.$B$BПрошу тебя, $n, верни мне ящик, без него я как без рук.','','','','','',''),
(144,'Гонец в Западный Край','Вернитесь к чиновнику Соломону с ответом Гриана Камнегрива.','Меня очень огорчило письмо мирового судьи Соломона. К сожалению, он не ведает о войне, начавшейся в Западном Крае, иначе не ждал бы помощи от нас. Нам самим без ополчения не обойтись, потому что Штормград бросил нас на произвол судьбы.$b$bОтнеси мой ответ в Красногорье, |3-6($c), и передай своему хозяину, что я скорблю всем сердцем о гибели отважных бойцов.','','','','','',''),
(146,'Гонец в Темнолесье','Вернитесь к мировому судье Соломону с ответом лорда Элло Чернодрева.','Не знай я мирового судью Соломона лично, решил бы, что он сошел с ума. Послать в Приозерье Ночной дозор, потому что Штормград отказал в помощи? Мы и создали его, когда земли наводнила нечистая магия, а Штормград бросил нас на произвол судьбы. Если я пошлю в Приозерье Ночной дозор, то наш город падет, едва лишь Дозор доберется  до края леса.$B$BОтнеси мой ответ своему господину в Приозерье.','','','','','',''),
(148,'Припасы из Темнолесья','Поговорите с мадам Евой.','Как же быть несчастному старику?.. Мне нужно привезти кое-что из Темнолесья, но деревня так далеко, а я стар и слаб... Мне не добраться до цели.$B$BНе $gмог:могла; бы ты отправиться в Темнолесье и привезти мне нить из призрачных волос? Ее можно приобрести у мадам Евы, которая живет на центральной площади города.','','','','','',''),
(153,'Красные кожаные банданы','Принесите разведчику Галиану на Сторожевой холм 15 красных кожаных бандан.','В Братстве Справедливости идет постоянная кипучая деятельность. Я уже долго слежу за их передвижениями. Между прочим, я заметил, что многих бандитов можно опознать по красным кожаным банданам.$b$bПринесите мне 15 таких бандан, и я позабочусь о том, чтобы вы получили вознаграждение.','','','','','',''),
(154,'Гребень для Эвы','Верните гребень для призрачных волос мадам Еве в Темнолесье.','НЕТ!!!$B$BУбери его, убери от меня этот гребень!$B$BЯ чудовище, меня больше никто не назовет прекрасной!','','','','','',''),
(157,'Доставка ниток','Принесите нить из призрачных волос в хижину на севере от кладбища Вороньего холма и отдайте ее Аберкромби.','Вот тебе нитки, $n. Им можно найти тысячи способов применения – от связывания злых духов до зашивания жизни в бездушные предметы.','','','','','',''),
(158,'Сок зомби','Поговорите с хозяином таверны Смиттсом.','Мне нужна бутылка особого напитка – сока зомби. У хозяина темнолесской таверны "Алый ворон" Смиттса наверняка найдется лишняя бутылочка.$B$BТоропись, $n. Ночи стоят холодные, и мне не терпится снова наполнить жилы огнем.','','','','','',''),
(160,'Записка для мэра','Отнесите письмо Аберкромби Элло Чернодреву, мэру Темнолесья.','Отнеси эту записку Элло Чернодреву, мэру Темнолесья.$B$BМы с ним старые друзья... И когда он прочитает это и узнает, что ты для меня $Gсделал:сделала;... не сомневаюсь, он будет счастлив не меньше меня! Ха-ха-ха!!!','','','','','',''),
(174,'Взгляни на звезды','Принесите Виктору Призм''Антрасу бронзовую трубку.','Один мой друг, гном по имени Ког, обещал мне помочь создать устройство, которое позволит изучать звезды. Уверен, что есть и иные объяснения творящемуся в лесу, чем магическое вмешательство.$B$BПринеси мне бронзовую трубку, изготовленную искусным инженером. Согласно чертежам Кога, это шаг номер один.','','','','','',''),
(175,'Взгляни на звезды','Найдите Мэри и уговорите ее пожертвовать зеркало для проекта Виктора.','Согласно чертежам Кога, мне нужно отыскать способ отражать свет. Помнится, есть у нас одна особа по имени Мэри, которая вечно таскает с собой зеркальце. Может быть, ты отыщешь ее и она одолжит нам свою отражающую поверхность? Кажется, она когда-то жила в южной части Сумеречного леса.','','','','','',''),
(177,'Взгляни на звезды','Заберите зеркало Слепой Мэри у Невменяемого Вурдалака и отдайте его Виктору в Темнолесье.','Зеркальце было одним из моих главных сокровищ... но потом со мной случилось несчастье. После этого я зашвырнула стекляшку за амбар. Одно время там бродил Невменяемый Вурдалак. Может быть, он утащил мое зеркальце. Говорят, что теперь эта тварь живет на Безмятежном кладбище.','','','','','',''),
(222,'Воргены в лесу','Калор просит вас убить 8 Ярых Клыков из стаи Ночной Погибели и 8 нечистых воргенов из стаи Ночной Погибели.','Твои прежние достижения наводят меня на мысль, что ты можешь схватиться с сильнейшими из воргенов, наводнивших наши леса.$b$bСамими опасными из всех оказались Ярые Клыки и нечистые воргены. Они живут рядом с пещерами и в руднике на юге.$b$bЗарево их костров видно издалека.','','','','','',''),
(225,'Заброшенная могила','Поговорите с Широй Фон-Инди в Темнолесье.','Надпись на древнем могильном камне гласит:$B$BМОРГАН ЛАДИМОР$b$b*При внимательном рассмотрении вы замечаете, что могилу недавно раскапывали, и большая часть земли насыпана заново...*','','','','','',''),
(228,'Мор''Ладим','Убейте Мор''Ладима и отнесите его череп командиру Альтее Чернодрев в Темнолесье.','Разведчики сообщают, что Мор''Ладим бродит по кладбищу. Мы похоронили его за домом на холме, знаешь, где это?$b$bБольше я тебе ничем помочь не могу... Разве что пожелать удачи.','','','','','',''),
(230,'Лагерь Свена','Принесите Свену книгу, найденную на ферме Свена.','Порывшись в груде земли, вы находите небольшую книгу, перепачканную грязью.$B$BНа ней нет заглавия, зато в ней содержатся сведения, необходимые Свену.','','','','','',''),
(240,'Возвращение к Трясунчику','Отнесите Трясунчику темные пирожки с крабами.','А вот и пирожки с "крабами" а-ля Груал!','','','','','',''),
(253,'Невеста Бальзамировщика','Отыщите могилу Элизы. Извлеките из нее сердце Бальзамировщика и вернитесь к Элло Чернодреву.','Бальзамировщиком в наших краях давно пугают детей. Когда-то он был добрым алхимиком, но смерть любимой жены Элизы лишила его рассудка. Чтобы вернуть ее к жизни, он прибег к темной магии и даже вложил в грудь мертвой супруги собственное сердце.$B$BЭто оживило Элизу... но ее сразило проклятие – она возжелала человеческой плоти, и Бальзамировщику пришлось закопать ее обратно.$B$BВсе его могущество заключено в сердце. Отыщи могилу Элизы, извлеки из нее сердце и принеси его мне, пока оно бьется. Если тебе удастся выполнить это, то сила Бальзамировщика иссякнет.','','','','','',''),
(262,'Таинственный незнакомец','Отнесите книгу, обнаруженную на ферме Свена, в Темнолесье и покажите ее горожанам.','Я должен узнать, кто таился в тени в ту ночь, когда была убита моя семья!$b$bПрошу тебя, $n, помоги мне. Ты не раз $gтворил:творила; настоящие чудеса. Выясни, кто это был. Мне нужно узнать его тайны!$B$BЯ рассказал тебе все, что мог, но возьми эту книгу, обнаруженную на ферме. Может быть, кто-то в городе опознает ее, и мы выясним имя владельца?','','','','','',''),
(265,'Продолжение поисков незнакомца','Поговорите с горожанами о таинственном незнакомце.','Вот твоя книга, $n, желаю удачи в расследовании. Если ты расспросишь других горожан, они могут рассказать тебе что-нибудь ценное.$B$BЯ же скажу одно: хотя автор этой книги не из нашего города, тетрадь для нее он купил здесь.','','','','','',''),
(266,'Расспросы в таверне','Найдите в таверне улики, связанные с таинственным незнакомцем.','Вот твоя книга, желаю удачи в расследовании.$B$BСоветую заглянуть в таверну. Если человек, о котором ты говоришь, останавливался у нас в городе, скорее всего его кто-то видел.','','','','','',''),
(268,'Возвращение к Свену','Отнесите Свену законченные записи Трясунчика.','Я лишь наполовину успел закончить книгу, найденную тобой. Мне пришлось оставить ее на ферме Свена во время поспешного бегства…$B$BВот. Отнеси Свену все мои записи. Здесь подробно рассказывается о случившемся на ферме.$B$BХотя единственным моим сокровищем в последние несколько недель были только эти записи, я охотно расстанусь с ними, лишь бы не вставать на пути Свена!','','','','','',''),
(270,'Обреченный флот','Отправляйтесь в Гавань Менетилов в Болотине и поговорите с дворфом по имени Глорин Стальной Лоб.','Много лет назад Третья флотилия Кул-Тираса затонула у берегов Болотины, огромной топи к северу от дворфийского королевства Стальгорна. Одно из судов было нагружено светлой сталью.$b$bЭтот металл представляет для нас большую ценность, поскольку изготовленное из него оружие и доспехи разят врагов силой святой истины. Если вы собираетесь противостоять Морбенту Скверну, вам именно такое оружие и понадобится.$b$bОтправляйтесь в Гавань Менетилов и переговорите с моим коллегой-дворфом по имени Глорин Стальной Лоб. Если утерянный груз еще можно найти – он сообразит, где нужно искать.','','','','','',''),
(271,'Месть Вайрины','Убейте Старину Черношкура и принесите его голову Дэрилу Юному в Приюте странников.','Не хочешь отплатить Его Смелости? Вынуждена признать, что Дэрил в самом деле многое умеет.$b$bГод назад весь Приют странников охотился на огромного медведя, но ни одному смельчаку не посчастливилось его одолеть. Тогда Дэрил решил выступить против зверя сам. Разумеется, он ничего не добился, да еще и получил этот уродливый шрам над глазом.$b$bУбей медведя, и не сомневаюсь, что даже Дэрил ненадолго лишится дара речи.$b$bСтарину Черношкура можно отыскать в логове в холмах над Телcамаром.','','','','','',''),
(274,'Прямая и черная угроза','Сообщите главному инженеру Камнехмылу о нейтрализующем коллоиде.','Это не простой взрывчатый порошок. Только взгляни на эти крошечные серебристые кристаллы. А характерный запах! Ясно, как день – это сефорий. Сам по себе он безобиден, но, намокнув, может взорвать весь Стальгорн!$b$bХимическую реакцию можно нейтрализовать, смешав четыре компонента: паучий яд, толченый кристалл Могроша, слезу кроколиска и нейтрализующий коллоид. Расскажи об этом Плотине, пока не поздно!','','','','','',''),
(275,'Нарывы на теле земли','Убейте 12 трясинных ползунов и вернитесь к Ретилю Стражу Природы в Болотину.','Болотину лихорадит, и я не знаю почему. Трясинные ползуны набирают силу. Это болезненные, гнойные нарывы на теле земли! И чтобы исцелить ее, нужно загнать трясинных ползунов обратно в болота, откуда они вылезли.$B$BПолзуны водятся у водоемов в Болотине.','','','','','',''),
(288,'Третья флотилия','Купите первому помощнику Фитсиммонсу кружку медовухи.','Когда-то я был первым помощником на "Владычице", линейном корабле кул-тирасской Третьей флотилии. Обреченной флотилии... Во время последнего плавания на нас напали красные драконы. А ими правили орки!$B$BУ нас не было ни единого шанса спастись от драконьего огня, и все корабли были сожжены и потоплены у побережья. Я один уцелел в этом кошмаре.$B$BОх, как же раскалывается голова! Погоди, сейчас я выпью чего-нибудь, немного приду в себя и продолжу.','','','','','',''),
(290,'Очищение','Возьмите ключ от сейфа на "Отважном" у капитана Халиндора.$B$BОткройте сейф на "Отважном".','Чтобы избавиться от проклятия и освободить моих верных товарищей, нужно найти и очистить эту... проклятую штуковину... спрятанную на моем корабле! Не знаю, что это такое, знаю только, что эта штука хранится в корабельном сейфе, а ключ от сейфа – у капитана Халиндора.$B$BСтарина капитан снится мне до сих пор. Я знаю, он сейчас на "Отважном" – нашем несчастном корабле. Постарайся добыть ключ от сейфа, открой его и возьми эту вещь.$B$BПотом отнеси ее в город и отдай жрецу Глорину Стальному Лбу.','','','','','',''),
(294,'Месть Ормера','Убейте 10 крапчатых ящеров и 10 крапчатых крикунов.','Придется признать, что положение отчаянное. Когда мы раскопали эти кости, ящеры немедленно атаковали нас. Многие из братьев были разорваны на месте, а я, Меррин и бедолага геолог оказались в ловушке здесь, наверху.$b$bПомоги очистить Болотину от ящеров, $n. Крапчатые ящеры и крапчатые крикуны водятся к западу от этого утеса. Убей по 10 тварей каждого вида.$b$bЭто будет началом моей мести.','','','','','',''),
(296,'Месть Ормера','Убейте Зарлозуба и принесите Ормеру Сталеплету один из когтей чудовища.','Пока тебя не было, я заметил, что среди этих тварей есть один выдающийся экземпляр. Он крупнее остальных и отличается особой свирепостью. Могу поклясться, что он – их вожак, это он привел их сюда и подначил разорить шахту.$b$bСослужи мне последнюю службу, $n. Зарлозуба надо предать правосудию. А если принять во внимание тяжесть его преступлений, правосудие здесь может быть только одно: смерть на месте! Убей его и в доказательство принеси мне один из его когтей.','','','','','',''),
(306,'Пропавшие ученые','Отнесите Таррелу Камнепряду записку от Меррин.','Это было ужасно! Мы обнаружили несколько очень редких артефактов. Пока мы занимались раскопками, нам все чаще и чаще начали попадаться огромные кости.$b$bВсе случилось внезапно. На нас напали крапчатые ящеры, их было значительно больше, чем нас. Почти все наши погибли в неравной схватке.$b$bОстались только мы трое. Ормер – он такой храбрый, настоящий герой, – спас меня и геолога, он прикрывал нас, пока мы бежали в укрытие. А теперь мы в ловушке и вся наша работа пропала!$b$bВот, отнеси эту записку моему дорогому Таррелу. Я ему все написала подробно. Он разберется.','','','','','',''),
(323,'Доказательство силы','Убейте 15 скелетов-налетчиков, 3 скелетов-лекарей и 3 скелетов-хранителей и вернитесь к Свену.','Морбент Скверн – могущественный некромант и союзник темных всадников. Я не могу послать тебя на битву с ним, не испытав прежде твою силу.$B$BХрабрость твою я не подвергаю сомнению, но если ты в самом деле хочешь выступить против некроманта, сразись сначала с его приспешниками.','','','','','',''),
(350,'Помощь старого друга','Поговорите с Иллингом Триасом в Штормграде.','Марзон наверняка поддерживает контакт с Братством Справедливости, и у него есть выход на Лесковара...$B$BТеперь, когда ван Клиф и Тредд погибли, Лесковара будет нелегко посадить на скамью подсудимых, потому что без их показаний твое свидетельство ничего не будет значить; стоит также принять во внимание благородное происхождение и хорошие связи Лесковара. Ему, в сущности, наплевать на закон.$B$BТебе понадобится помощь. Я, увы, оказать ее не могу, но знаю того, кто может нам помочь. Найди Триаса в Торговом квартале.','','','','','',''),
(378,'Успокоить гневливого','Принесите голову Кама Гневливого Мотли Каменщику в Дун Модр.','Ты $Gдоказал:доказала; свою преданность королю Магни, |3-6($c). И ты, так же как я, ненавидишь мерзавцев Черного Железа всем сердцем.$b$bЯ бы сам взялся за эту работу, но я дал слово чести и должен быть рядом с Длинной Косой. Рогго говорит, что у него есть доподлинные доказательства: это Кам Гневливый организовал нападение на мост Тандола. А это значит, что Кам виноват в гибели брата Длинной Косы.$b$bПока что Кама Гневливого держат в тюрьме Штормграда. Но такие, как он, не достойны того, чтобы жить. Убей его, $n. Ради Грима! Принеси мне его голову!','','','','','',''),
(392,'Таинственный посетитель','Отнесите запечатанное описание посетителя Тредда Баросу Алекстону в Штормград.','Во время первого года заключения Тредда никто его не навещал. Мне казалось, что братство отказалось от него, поскольку он стал бесполезен.$B$BНо пару месяцев назад его стали постоянно навещать – раз, два в неделю. Посетитель был весьма странный. Такой тихий тип. У меня возникли подозрения, но все его документы были в полном порядке.$B$BСогласно документам, звали его Мелик; вот его описание. Не думаю, что он еще когда-нибудь придет к Тредду.','','','','','',''),
(393,'Тень прошлого','Отнесите запечатанное описание посетителя Тредда Матиасу Шоу в Штормград.','Знаете ли, $n, мне так ничего и не пришло в голову. Зато я придумал, кто может нам помочь; если так и случится, я буду гордиться собой, но не стоит на это закладываться. Матиас Шоу из ШРУ – его можно найти в казармах Старого города. Шоу знает все уголки и закоулки этого города, всю его подноготную и тайные делишки.$B$BЕсли кто-то и знает, о ком речь, то только он.','','','','','',''),
(416,'Ловля крыс','Принесите 12 ушей кобольдов-туннельщиков горному пехотинцу Кэдреллу в Телсамар.','К западу отсюда началось настоящее нашествие. Эти крысы, кобольды-туннельщики, обосновались в предгорьях, устроили там свои логовища и оскверняют нашу прекрасную землю!$b$BИх необходимо истребить. Перебей их как можно больше, принеси в доказательство уши и получишь награду.$B$BКобольды-туннельщиков поселились к западу от Телcамара вдоль горных склонов.','','','','','',''),
(434,'Нападение!','Спрячьтесь в саду и подслушайте разговор лорда Грегора Лесковара и Марзона Бесшумного Клинка. После этого убейте обоих и возвращайтесь к Иллингу Триасу в Штормград.','Сейчас я переодену своего робота-шпиона, и он отправится на аудиенцию к Лесковару. Гвардия пропустит его без особых проблем.$B$BПока ты $Gсобирал:собирала; для меня материалы, я дал Марзону идейку, которую он непременно захочет обсудить с Лесковаром. Я даже подкинул ему пару ложных слухов.$B$BЛесковар отпустит свою охрану и будет дожидаться Марзона в саду. Начинай действовать, как только они заведут разговор о Братстве Справедливости. Убей обоих до возвращения гвардейцев! После этого поговори с Триасом.','Подслушайте разговор Лесковара и Марзона','','','','',''),
(453,'Поиски таинственного незнакомца','Отыщите незнакомца. Его приметы:$B$BОн родом не из Темнолесья.$B$BОн – нервный тип.$B$BОн сбежал из Темнолесья и двинулся на запад.','Удачи, $n. Надеюсь, ты найдешь этого парня, причем живым.$B$BСбежав за пределы Темнолесья, он мог пасть жертвой диких зверей.','','','','','',''),
(474,'Убить Нек''роша','Убейте вождя Нек''роша.$B$BПринесите голову Нек''роша капитану Крепкому Кулаку.','Катапульты сожжены. Теперь найди и убей вождя Нек''роша.','','','','','',''),
(536,'На побережье','Убейте 10 волноловов из племени Порванного Плавника и 10 оракулов из племени Порванного Плавника по поручению лейтенанта Фаррена Оринеля из Южнобережья.','Меня перевели в Южнобережье из городской стражи Штормграда. Непонятно, как тут вообще люди живут... А как воняет со стороны пристани и днем и ночью!$b$bДа еще старый Редпат на мою голову... Он хочет, чтобы я занялся мурлоками. Ха!$b$bЯ едва могу заставить себя подойти к этим рыбам-переросткам на Западном побережье. Если ты разберешься с ними вместо меня, я буду очень признателен.','','','','','',''),
(633,'Мост Тандола','Уничтожьте взрывчатку.','Во имя Света, только не это! Бедняга Ржавый Засов. Ты меня $gопечалил:опечалила;, $n.$b$bНо его жертва не будет напрасной! В пергаменте сказано, что Кам Гневливый – тот, кто организовал нападение, – приказал заложить взрывчатку под мостом Тандола на границе с нагорьем Арати.$b$bЕсли ему удастся очередная диверсия, то мы лишимся поставок с севера! Взрыв нужно предотвратить. Сделай все возможное, чтобы спасти мост Тандола, и возвращайся ко мне.$b$bТы – наша единственная надежда.','','','','','',''),
(865,'Рога ящера','Соберите 5 невредимых рогов ящера с ящерочешуйчатых смертехватов и отнесите их Мебоку Миззриксу в Кабестан.','Ящеры Степей умнее, чем прочие. Мне кажется, весь ум в рогах! Если так, эти рога можно стереть в порошок и сделать из них "умный напиток". Я мог бы продавать его за баснословные деньги!!!$B$BТы можешь мне помочь. Принеси мне целые рога ящерочешуйчатых смертехватов. Они живут в южной части Степей и на севере, рядом с границей Ясеневого леса.','','','','','',''),
(887,'Флибустьеры Южных морей','Убейте 12 грабителей Южных морей и 6 канониров Южных морей по просьбе Газула из Кабестана.','Жаль, что вице-адмиралу Греззлику не удалось добиться безопасности в наших водах для торговых кораблей. В торговый флот вложено столько денег, что я просто зверею, когда пираты как нечего делать нападают на мои корабли и похищают товары! $b$bГоворят, что флибустьеры Южных морей разбили лагерь к югу отсюда. Они мне как бельмо на глазу, и если ими не хочет заняться Греззлик, может быть, ты поможешь избавиться от них?','','','','','',''),
(895,'РАЗЫСКИВАЕТСЯ: Барон Дольноберег','Принесите Газулу в Кабестан голову барона Дольноберега.','РОЗЫСК! $b$bРазыскивается Барон Дольноберег, капитан "Безрассудной".$b$BКапитан Дольноберег из Гильнеаса водит корабли корсаров Южного моря. Он разыскивается по обвинению в пиратских нападениях. Предоставленные останки должны быть пригодны для опознания!$B$B- Газул.','','','','','',''),
(944,'Меч Властителя','Соберите информацию, а затем используйте фиал виденья для создания гадальной чаши. С помощью чаши поговорите с Ону.','Очень странно, что наги появились здесь, на Темных берегах. Но еще страннее – клан Сумеречного Молота. Они поклоняются старым, очень старым богам этой земли. Богам, давным-давно низвергнутым.$b$bМеч Властителя, что к югу отсюда, – место, где пал один из этих древних богов.$b$bПойди туда и поищи других культистов Сумеречного Молота.$b$bВозьми этот фиал виденья. Используй его для создания гадальной чаши, когда разведаешь все у Меча Властителя. Посредством этой чаши поговори со мной.','Отправляйтесь в Меч Властителя.','','','','',''),
(968,'"Подземные Силы"','Принесите книгу "Подземные Силы" Геррику Костохвату в Заброшенный грот в Стальгорне.','Хотя книга ужасно истрепана и исцарапана, ее название на обложке все же можно разобрать:$b$b"Подземные Силы".$b$bВ книге перечисляются непроизносимые имена со зловещими титулами, способами почитания и предпочтительными жертвоприношениями... И среди этих жертвоприношений числятся живые разумные создания.$b$bНа внутренней стороне обложки написано: "Руны и Жребии Костохвата, Заброшенный грот, Стальгорн. Владелец: Геррик Костохват".$b$bЕсли Костохват торгует подобными книгами, может быть, он выкупит эту?','','','','','',''),
(973,'Башня Алталакса','Принесите фолиант Илкруда Магтрулла Делгрену Очистителю на заставу Мейстры.','Илкруд Магтрулл. Да, я знаю о нем. Это могучий орочий чернокнижник, который поселился в Святилище Огненной Расщелины, месте великого зла на юго-западе Ясеневого леса.$b$bДоныне он был не более чем досадной помехой, потому я и не трогал его, но, похоже, пришла пора с ним разобраться.','','','','','',''),
(986,'Пропавший хозяин','Найдите 5 прекрасных шкур лунопарда и принесите их Терентису в Аубердин.','$n, ваше мастерство уже один раз сослужило мне хорошую службу в сложной ситуации. Могу ли я вновь возложить на вас задачу помочь Мрачнокогтю и его хозяину Волкору? Я могу сделать для вас волшебный плащ, который позволит вам беспрепятственно ходить вблизи враждебных существ Темного Берега, пока вы будете искать Волкора.$b$bДля изготовления плаща, чтобы хватило материала, мне нужно 5 прекрасных шкур лунопарда, снятых со взрослых самцов или матриархов. Этих кошек можно найти около Петляющей реки, к югу отсюда, или еще дальше на юг, близ Ясеневого леса.','','','','','',''),
(993,'Пропавший хозяин','Найдите Волкора на Темных берегах и отдайте ему зачарованный плащ лунопарда.','Плащ готов, $n. Пришло время найти Волкора. Я могу только надеяться, что мы успеем.$b$bМагия, скрытая в плаще, если ее пробудить, продержится недолго: может быть, минут пять. $GСам:Сама; решай, когда использовать: я бы предложил подождать, пока не найдешь Мрачнокогтя.$b$bЕсли то, что он сказал мне – правда, ты найдешь его хозяина в пещере к югу отсюда. Мрачнокоготь будет ждать тебя у дороги. Помаши ему, когда увидишь, чтобы привлечь его внимание, и он укажет тебе путь к своему хозяину.','','','','','',''),
(1007,'Древняя статуэтка','Принесите древнюю статуэтку Талену в его лагерь близ Зорамского взморья.','Я хотел бы дать тебе поручение, $n.$B$BЯ на своей маленькой лодочке плыл над затопленными руинами Зорама, когда на меня напали наги, выныривая из воды и вцепляясь в меня когтями! Я убежал, унеся с собой все, что смог, и чего хватило лишь вот на этот жалкий лагерь.$B$BНо когда я добрался до берега и побежал... я потерял одну дорогую мне вещь.$B$BПрошу тебя, $n, найди место засады – это на побережье к северу – и отыщи древнюю статуэтку. Именно из-за нее я отважился подвергнуть себя опасностям Зорамского взморья.','','','','','',''),
(1008,'Зорамское взморье','Принесите 20 голов наг из клана Зловещего Хвоста Шиндрелл Огненный Всполох в Астранаар.','По нашему северо-западному побережью, известному как Зорамское взморье, расползается зло.$B$BТам покоятся руины злосчастного города Зорам, разрушенного при Расколе и поглощенного морем. Для ночных эльфов он был утрачен на много веков. Утрачен и почти забыт.$B$BТеперь туда вернулись наги, и мы не знаем, почему. Но причина не так важна – мы должны перебить этих тварей и загнать их обратно в глубины!$B$BВозвращайся, когда выполнишь поручение.','','','','','',''),
(1013,'Книга Ура','Принесите книгу Ура хранителю Бел''дугуру в Квартал аптекарей в Подгород.','$n, в крепости Темного Клыка хранится книга – книга Ура, я хочу видеть ее в своей коллекции. Ур был великим магом Даларана до того, как оказался в рядах Плети, и его труды по иным мирам представляют большой интерес... для некоторых Отрекшихся.$B$BОтправляйся в крепость Темного Клыка и найди книгу. Принеси мне ее, и я сообщу о твоих заслугах Темной Госпоже.','','','','','',''),
(1014,'Смерть Аругалу!','Убейте Аругала и принесите его голову Далару Ткачу Рассвета в Гробницу.','Аругал по-прежнему сидит в крепости Темного Клыка. Мы не можем считать Серебряный бор стратегическим оплотом Темной Госпожи до тех пор, пока Аругал жив. $b$bЯ позабочусь о том, чтобы искоренить его магию, $n. Но сделать так, чтобы Аругал встретил заслуженную смерть – это я оставляю вам. $b$bОтправляйтесь в крепость Темного Клыка и положите конец скверным деяниям Аругала раз и навсегда. И принесите мне голову этого злодея!','','','','','',''),
(1016,'Браслеты элементалей','Соберите 5 неповрежденных браслетов элементалей, а затем задействуйте на них гадальный свиток. После отнесите разгаданный свиток Стражу Велене Звездный Всполох в Приют Серебряного Ветра.','Бозьми этот гадальный свиток – он поможет определить создателя этих элементалей. Но тебе понадобится кое-что взять у этих духов для фокусировки магии свитка – их браслеты прекрасно подойдут.$B$BХватит нескольких неповрежденных браслетов с этих существ. Другие для наших целей бесполезны, но зато у торговцев за них можно кое-что выручить, если пожелаешь продать. Как только ты добудешь неповрежденные браслеты, попытайся использовать свиток. Возвращайся ко мне с результатами, и мы продолжим.','','','','','',''),
(1021,'Сатиры коварны! Дриады в опасности!','Найдите в Ксавиане Анилию.','Послушай, я не знаю, кто ты, но мне нужна помощь. Мои сестры отправились отнять у одного сатира Ветвь Кенария. Они сказали, что скоро вернутся, но уже целых два дня прошло!$B$B$n, ты $Gдолжен:должна; найти их! Они искали развалины храма ночных эльфов в Ксавиане на северо-западе. Не знаю, что и думать. Найди Анилию, это она повела их на поиски.','','','','','',''),
(1024,'Раэна – санитар Ясеневого леса','Найдите Шаэлдрин у лунного колодца на северо-востоке.','Тебе придется провести исследование самостоятельно, но, судя по заметкам Терониса, следующим твоим шагом, похоже, будет поиск остальных фрагментов созданного Дартолом жезла. Я бы начала поиск от лунного колодца к востоку от озера Ирис. Когда будешь $Gготов:готова;, ступай по этой дороге и сверни на север у небольшого местечка для отдыха слева от тебя.$B$BДриада Шаэлдрин будет тебе лучшим, чем я, проводником. Найди ее.$B$BВозьми с собой этот самоцвет – он может понадобиться Шаэлдрин, если она решит помочь тебе восстановить жезл.','','','','','',''),
(1025,'Лучшая защита – нападение','Убейте 1 дозорного, 2 ведмедей, 10 тотемистов и 12 воинов из племени Гиблой Чащи, а затем вернитесь к Раэне Волкопас в Астранаар.','Если ты желаешь испытать свои умения и заодно помочь жителям Ясеневого леса, я дам тебе еще одно поручение, прежде чем ты отправишься к лунному колодцу.$B$BНа дороге, что сворачивает на восток перед рекой Фалфаррен, фурболги в последнее время нападают на путников. Их извращенный разум питается страхом, а кровожадность утоляется кровью невинных жертв.$B$BПомоги часовым защитить эти края, отплати этим чудовищам их же монетой.$B$BДумаю, их лагерь находится к югу от дороги... будь $Gосторожен:осторожна;.','','','','','',''),
(1026,'Раэна – санитар Ясеневого леса','Найдите деревянный ключ и обломок жезла Дартола прежде, чем вернуться к Шаэлдрин у Лунного колодца.','Хотелось бы мне, чтобы у тебя были более хорошие новости.$B$BРаэна права, я знаю о творении Дартола и  древнях этих краев – или знала прежде. Они теперь все осквернены, их природа искажена.$B$BЕсли твоя цель – найти еще один фрагмент жезла, то тебе придется найти ключ, чтобы отпереть сундук, в котором он лежит.$B$BДеревянный ключ – на одном из древней к северу отсюда, близ Оскверненного леса. Как только добудешь его, ищи небольшую лощинку к западу от дороги близ границы Оскверненного леса... Сундук должен быть спрятан где-то там.','','','','','',''),
(1034,'Руины Звездной Пыли','Принесите 5 горстей звездной пыли Пельтуру в Астранаар.','Слеза Элуны немного облегчила страдания моей дочери. Кошмары стали реже ее мучить, хвала богине. Но... лихорадка все еще сжигает ее.$B$BОрендил рассказал мне о морозной пыли, которую находят среди руин Звездной Пыли. Может, она усмирит лихорадку Релары. Собери немного этой пыли, прошу тебя, и принеси ее мне.$B$BРуины Звездной Пыли находятся на юге, $n. Да ускорит твой шаг Элуна!','','','','','',''),
(1037,'Велинда Песнь Звезд','Поговорите с Тин''тель Танцем Клинка на террасе Воинов в Дарнассе.','Велинда Песнь Звезд была моей предшественницей здесь, в Ясеневом лесу. Поначалу казалось, что она держдит под контролем ситуацию в Оскверненном лесу, но понемногу ее усилия стали сходить на нет. И однажды она просто исчезла.$b$bМеня послали сюда продолжить ее труды. Однако, боюсь, я ничего не знаю об этой жрице. Возможно, Тин''тель Танец Клинка, одна из командиров часовых, знает подробности ее исчезновения, о которых не знаю я.$b$bНаверняка она поймёт значение такой информации.','','','','','',''),
(1050,'"Мифология Титанов"','Добудьте "Мифологию Титанов" из монастыря и принесите ее библиотекарю Мае Белокожке в Стальгорн.','Будущее неотвратимо! Мы стремимся к нему подобно тому, как дождевые капли стремятся к Великому морю.$b$bНо, изучая прошедшее, мы узнаем, что ждет нас в грядущем, и готовимся к встрече с неведомым.$b$bПрежде чем великие беды обрушились на Лордерон, в Тирисфальских лесах находился оплот знаний. Ходят слухи, что в библиотеке старого монастыря хранится книга под названием "Мифология Титанов".$b$bПринеси ее мне – и, возможно, вместе мы сможем заглянуть в тайны прошлого!','','','','','',''),
(1054,'Устранение угрозы','Принесите череп Дала Жилотяга Раэне Волкопас в Астранаар.','Прямо к северу от Астранаара живут фурболги Колючего Меха. Мои разведчики доносят, что в последние несколько месяцев они чрезвычайно умножились числом. Если они слишком расплодятся, то могут набраться наглости напасть на Астранаар!$B$BУбей их, сколько сможешь, главное – принеси мне череп их предводителя в знак того, что их усилия напрасны...пока. $B$BЯ останусь в Астранааре и буду ждать вестей от тебя. Да пребудет с тобой Элуна.','','','','','',''),
(1056,'Путешествие к Пику Каменного Когтя','Отправляйтесь к хранителю Албагорму на Пик Каменного Когтя.','Лесные духи говорят мне, что ты $Gотважен и легок на подъем:отважна и легка на подъем;.$b$bНа юге, неподалеку от озера Мистраль, находится туннель, именуемый Туннель Когтя. Через этот туннель ты попадешь в место, называемое Утес Ветрорезов, в Когтистых горах. Попав туда, иди на юго-запад мимо Скалистого озера, а затем на север, вверх по крутому склону, пока не доберешься до Пика Каменного Когтя.$b$bТам ждет хранитель Албагорм. Выслушай его просьбу, |3-6($r).$b$bПутешествие будет опасным.','','','','','',''),
(1070,'На страже в Когтистых горах','Найдите Келу Копье Тени, которая наблюдает за долиной, выходящей к Утесу Ветрорезов в Когтистых горах.','Привет тебе, $n.$B$BСудя по виду, ты много путешествуешь. Тебе приходилось бывать в Когтистых горах? Эта земля опустошена Торговой компанией и прочими врагами ночных эльфов. $B$BНедавно часовой Волкопас послала туда мою подругу Келу Копье Тени, чтобы она узнала, что происходит в тех землях, однако до сих пор от нее нет вестей. Я еще беспокоюсь и потому, что Альянс отправил вместе с ней гнома-мага... это, несомненно, повод для тревоги.$B$BМожет быть, ты найдешь ее и пошлешь весточку мне?','','','','','',''),
(1071,'Отсрочка для гнома','Убейте 10 лесорубов и 10 лесозаготовителей Торговой Компании и вернитесь к Гаксиму Ржавошиппи в Каменный Коготь.','Понимаешь ли, $n, я состою в Просвещенной Ассамблее Чародейства, Алхимии и Технических Наук, и моя цель... нет, мой ДОЛГ! – показать ночным эльфам, что единение магии, реактивов и механизмов поможет спасти их леса.$B$BОднако это тяжелая война, а гоблины, похоже, плодятся, словно кролики. У меня даже нет времени воплотить в жизнь свои новые изобретения!$B$BМне нужно время для планирования и организации. Но для этого мне потребуется твоя помощь – сдерживать натиск гоблинов у Утеса Ветрорезов к востоку отсюда...','','','','','',''),
(1072,'Старый коллега','Поговорите с Ломаком Демонтирсом в Стальгорне.','Устройство, о котором я думаю – моя самая продвинутая версия на сегодняшний день. Но мне нужно особое зелье, чтобы это устройство заработало. Я думаю, нам нужно добыть хороший состав, поскольку эта миссия может стать для тебя последней.$B$BА для этого нам нужно мощное взрывчатое вещество: нитромирглицероний.$B$BЕдинственный, кто может создать НГ-5, это мой старый приятель – Ломак Демонтирс. Поищи его в Городе Механиков.$B$BЕсли уговоришь его сделать для нас немного НГ-5, то я начну работать над размещением своих устройств.','','','','','',''),
(1094,'Дальнейшие указания','Доставьте запечатанный конверт Пароклапану в Степи.','В этом конверте – все сведения, которые я смог собрать до того, как меня выпнули за дверь... Внутренние документы Торговой Компании, кое-какие руководства, технические бумажки... О, и, конечно, чертежи "Супер-потрошителя 6000".$b$bПаровой Клапан обосновался в Кабестане в Степях. Тебе не доставит труда разыскать его, это такой мелкий зеленый тип.','','','','','',''),
(1098,'Пропавшие стражи смерти','Найдите стражей смерти Адаманта и Винсента.','Готовясь к нападению на крепость Темного Клыка, мы отправили на разведку двух стражей смерти. Они не возвращаются вот уже много дней, но без их отчета нам не организовать успешного нападения!$b$bИтак, вот твое задание, $n. Отправляйся в крепость Темного Клыка на юге и найди стражей смерти Адаманта и Винсента. Найди их и помоги им, если сможешь.$b$bЭто очень опасное и важное задание, $n. Не подведи нас.','','','','','',''),
(1134,'Гордокрылы Каменного Когтя','Принесите 12 ядовитых желез славнокрыла Шиндрелл Огненный Всполох в Астранаар.','Между нами и Ордой война не объявлена, однако мир между нами очень хрупок. Мы часто обнаруживаем, что среди нас тайно действуют их агенты. $B$BОб одной такой операции мы узнали из скрытых источников в Тераморе. Эти источники утверждают, что орки собирают яд славнокрылов поблизости от Мутного Озера в Когтистых горах, на юге. А потом орочьи убийцы используют этот яд для тайных смертоносных ударов против сил Альянса!$B$BЕсли это правда, мы обязаны остановить их, $n. Мы должны лишить их источника яда.','','','','','',''),
(1244,'Пропавший дипломат','Найдите декларацию Братства Справедливости и верните ее дозорному Бакусу в Сумеречном лесу.','Опять братство?! Они вечно что-то вытворяют; даже если они затихли, мы считаем это недвусмысленной угрозой.$B$BКстати, сейчас я вспомнил, что последнюю пару недель их агенты так и кишат вокруг участка Эддла. Это подозрительно – должно быть, назревает какая-то крупная заварушка.$B$BНе хотите порыскать там и установить, в чем же дело?$B$BФерма находится к югу от дороги из Западного Края как раз на входе в Сумеречный лес.','','','','','',''),
(1339,'Задание Грозовой Вершины','Поговорите с горным пехотинцем Грозовой Вершиной.','Я слышал, что горный пехотинец Грозовая Вершина ищет гонца, который совершил бы по его просьбе небольшое путешествие. Сможет ли |3-6($r) вроде тебя справиться с его поручением?$b$BЕсли ты жаждешь приключений, ищи Грозовую Вершину на северной сторожевой башне.','','','','','',''),
(1580,'Электропеллеры','Принесите 12 электропеллеров Бацбаху Кривошипу в Аубердин.','Мы знаем, что тебе везет, но... насколько сильно везет, $n?$B$BОднажды ночью я бродил по дорогам Темного Берега. Я искал речку или озеро, пригодные для испытания моей самодвижущейся и взрывающейся подсадной утки и, думаю, был слегка пьян... поскольку потерял сознание и пришел в себя в Аубердине спустя несколько часов. Мои волосы были опалены, а сумка с электропеллерами исчезла! Должно быть, я уронил ее в воду!$B$BМне нужны эти электропеллеры! Может быть, тебе удастся выловить их из какого-нибудь водоема на Темном Берегу?..','','','','','',''),
(1650,'Фолиант Отваги','Найдите Дафну Стилвелл в Западном Крае.','Отлично! Отсутствие сомнений говорит о твоей готовности к испытаниям. Да будет так!$b$bВ самом конце Долгого Берега стоит небольшой домик с окнами на океан. Там живет чета Стивеллов. Джордан – великолепный кузнец, и сейчас он собирается в Стальгорн, чтобы навестить дворфов. Но его жена Дафна остается дома одна, без защиты...$B$bДонесения говорят, что Братство Справедливости захватило почти весь край. Дафне может понадобиться защита от злодеев. Отправляйся туда.','','','','','',''),
(1651,'Фолиант Отваги','Защитите Дафну Стилвелл от нападения Братства Справедливости. Проследите, чтобы ни ее, ни ваша душа в случае смерти не покинули свои тела, иначе испытание не будет засчитано.$b$BПосле победы поговорите с Дафной Стилвелл.','Бьюсь об заклад, они скоро вернутся – так что приготовься.$b$bВ доме есть пистолет, я возьму его и при необходимости помогу тебе, но лучше рассчитывай только на свои силы.$b$bНе знаю, сколько их будет, но уверена, что больше, чем в прошлый раз.$b$bМоли Свет благословить тебя, потому что… Слышишь? Они идут!$b$bУкроемся за домом!','Защитите Дафну Стилвелл.','','','','',''),
(1652,'Фолиант Отваги','Поговорите с Даторианом Раллом в Штормграде.','Прошу, возвращайся к Даториану и передай ему, что теперь со мной все в порядке – благодаря тебе и Церкви.$b$bОн пошлет весть в Стальгорн, чтобы мой Джордан не волновался за меня.$b$bОх, как я соскучилась по своему мужу! Жду не дождусь его возвращения...','','','','','',''),
(1654,'Испытание доблести','Возьмите список Джордана, добудьте немного древесины белокаменного дуба, партию очищенной руды Бэйлора, кузнечный молот Джордана и самоцвет Кора и отдайте их Джордану Стилвеллу в Стальгорне.','Я хотел бы отблагодарить тебя, если ты согласишься принять этот дар. Пойми меня правильно, все будет зависеть от того, насколько ты мне поможешь, но я вижу, что от такого сотрудничества обоим нам выйдет большая выгода.$B$BЯ скую для тебя оружие, достойное твоего деяния, оружие, что станет символом призвания паладина и пути Света. Но тебе придется добыть необходимые для ковки предметы. Я уже набросал список, так что остается только, чтобы некто отважный и искусный принес их мне. Что скажешь, |3-6($c)?','','','','','',''),
(1698,'Йорус Ячменовар','Поговорите с Йорусом Ячменоваром.','Йорус Ячменовар бросил вызов всем воинам Альянса. Он ждет в таверне Приозерья, что в Красногорье, и сулит щедрую награду всем, прошедшим испытание.','','','','','',''),
(1861,'Зеркальное озеро','Отнесите пробу воды из Зеркального озера Джиннии Пушке из Штормграда.','Этот мир пал жертвой магических войн, в результате которых нарушилось течение магической энергии. Мы попытались просчитать дальнейшие последствия, и многие из нас опасаются худшего!$b$bНо об этом мы поговорим позже. Для начала надо собрать все доступные сведения.$b$bВозьми этот сосуд, отправляйся к подножию водопада у Зеркального озера, что на юго-западе от Врат Штормграда, и принеси мне пробу тамошней воды. Я хочу исследовать ее на предмет заражения тлетворной магией.','','','','','',''),
(1880,'Маг-тастический гизмонитор','Верните Бинк маг-тастический гизмонитор.','Мы, маги, не просто щелкаем пальчиками и создаем забавные искорки! Мы контролируем поток магической энергии, основной ткани мироздания! Для этого требуется осторожность и решимость. И знания... Невероятно много знаний!$B$bОдно из моих устройств, маг-тастический гизмонитор, позволяет собирать и хранить множество знаний! Но увы, он утрачен! Когда мы бежали из Гномрегана, я оставила его в сундуке в одном из домишек за пределами города. Теперь там кишмя кишат лепрогномы!$b$bПрошу тебя, $n, верни мне гизмонитор!"','','','','','',''),
(1938,'Трактат Ура по темной магии','Принесите трактат Ура по темной магии верховному колдуну Андромату из Штормграда.','Давным-давно в этой башне жили три мага, и один из них поддался искушению и занялся темными искусствами. Его уговаривали отказаться от черной магии, но тщетно. И он был изгнан.$b$bНовое пристанище изгнанного мага – башня Илгалара в Красногорье. Он унес с собой ценную книгу – Трактат Ура по темной магии.$b$bМы, маги Штормграда, хотим вернуть себе эту книгу. Отправляйся в башню Илгалара, найди этот фолиант в библиотеке и принеси мне.','','','','','',''),
(2359,'Башня Клейвена','Добудьте ключ Башни Братства Справедливости, проберитесь в башню и выясните, каково содержимое сундука из Сумеречного леса. Отнесите найденные вещи Матиасу Шоу в Штормград. Почитайте дневник Кеарнен, чтобы больше узнать о башне.','Я за этой башней уже не первую неделю наблюдаю, $n. Недавно прошла крупная поставка из Сумеречного леса, а вместе с ней явились эти стражи.$b$bКто такие? Мы можем только гадать. Одно я тебе скажу: это не люди.$b$bКак бы то ни было, там был сундук – и, как я полагаю, эта мерзость именно его и охраняет. А ключ от сундука – у того зомби с шипами.$b$bДобудь этот ключ, проберись в башню и выясни, что находится в том сундуке. Находку отнесешь Матиасу.','','','','','',''),
(2360,'Матиас и Братство Справедливости','Найдите посланницу Кеарнен в Западном Крае и поговорите с ней.','Произошло то, чего я ожидал, $n. Разведотдел ШРУ сообщает, что Братство Справедливости что-то затевает в Западном Крае.$b$bСкладывается впечатление, что братство захватило покинутую сторожевую башню Альянса к юго-востоку от Сторожевого Холма и использует ее как базу для ввоза контрабанды из Красногорья.$b$bОтправляйтесь в Западный Край и свяжитесь с посланницей Кеарнен для подробного доклада. Она там прячется, неподалеку от башни.$b$b... и кстати, $n, если вас раскроют – вы никогда не слышали о ШРУ...','','','','','',''),
(2745,'Проникновение в крепость','Поговорите с Тирионом в Крепости Штормграда.','Хм-м, интересная история, причем не из тех, на которые можно наплевать. Да, помочь-то я вам могу, но то, что вам нужно будет сделать, это свершить правосудие... частично незаконным путем, если уж вы хотите довести дело до конца.$b$bС Лесковаром и Марзоном нужно разобраться – и быстро. Как думаете, вы на это способны?$b$bРешать вам. Если да, то поскорее отправляйтесь в крепость и найдите там моего старинного друга – гнома по имени Тирион. Он уже пару недель как наблюдает за Лесковаром. Он сможет помочь вам покончить с этим делом.','','','','','',''),
(2746,'Все по порядку','Принесите Тириону в Штормград 3 отреза шелка и 2 свежих яблока Клары.','Триас хочет поторопить события, так? Ладно, мы это сделаем, но сейчас я не готов. И, кстати, сложную часть я беру на себя, а ручки пачкать будете вы, это понятно? Отлично.$b$bЗначит, мне нужно, чтобы вы мне кое-что принесли, чтобы я смог воплотить в жизнь свой план. У меня есть мысль об отличной маскировке, при помощи которой этот робот-шпион пройдет мимо стражников.$b$bПринесите мне немного шелка и пару яблок. Где достать шелк – думайте сами, а вот подходящие яблоки есть у Клары в ее маленьком хозяйстве сразу за городской чертой.','','','','','',''),
(2962,'Сильное зеленое свечение','Отправляйтесь в Гномреган и принесите высокорадиоактивные образцы. Внимание: отходы нестабильны и довольно быстро разрушаются.$B$BВерните Оззи тяжелую освинцованную склянку для проб, когда задача будет выполнена.','Этого образца не только недостаточно для опытов, он еще и загрязнен.$B$BНам нужно более сильное зеленое свечение. Для наших целей эти трогги явно недостаточно облучены. Вам придется отправиться в Гномреган и принести некоторое количество радиоактивных образцов прямо с носителей. Я говорю об облученных слизнюках, шнырюках и ужасниках. Будьте начеку: образцы хранить очень трудно. Возможно, придется сделать несколько попыток, пока вы не принесете достаточное количество образцов.','','','','','',''),
(6123,'Сбор лекарственных ингредиентов','Принесите 5 корешков землекорня и 12 лунных грибов Аландариан Песне Ночи в Аубердине, чтобы она могла сделать целительную мазь.','Основой целительной мази для оленей послужит вода. Для придания ей целительных свойств мне понадобится землекорень. Травники знают, где его искать, так что, если нам не повезло и вы не $gтравник:травница;, придется найти кого-то, кто сможет помочь.$B$BДля усиления воздействия мне нужны лунные грибы. Найти их довольно легко: в пещерах, прямо на восток отсюда, их полным-полно. В этих пещерах обитают лунные совухи; в последнее время они стали очень раздражительны, так что будьте осторожны.','','','','','',''),
(8374,'Завоевание Низины Арати','Принесите 3 почетных знака Низины Арати бригадному генералу Альянса рядом со входом на поля боя.','Чтобы выиграть войну, мало быть быть умнее и хитрее противника. Зачастую победа достается тем, в чьих руках сосредоточены все ресурсы.$b$bРесурсов в Низине Арати – хоть отбавляй. Главное – захватить их первыми.$b$bЕсли победа будет за Альянсом, нашим солдатам достанется больше мечей и копий. Если Орде – те же мечи и копья обратятся против нас! Твой долг помочь Альянсу захватить Низину Арати!','','','','','',''),
(8399,'Битва за Ущелье Песни Войны','Принесите 3 почетных знака Ущелья Песни Войны бригадному генералу Альянса рядом со входом на поля боя.','Среброкрылые Часовые вступили в бой со всадниками из клана Песни Войны, стараясь защитить от них лес. Впрочем, желание сохранить этот лес объсняется не только их любовью к природе.$b$bЭтот лес представляет собой естественную преграду для наступления сил Орды. Без него Астранаар не продержался бы и дня, и в наши земли давно вторглась бы огромная армия Орды.$b$bВнеси свой вклад в борьбу со всадниками из клана Песни Войны, $n! За Альянс!','','','','','',''),
(65602,'Лучшие друзья','Добудьте деревянную статуэтку и принесите ее Гакину Темнопряду в квартал магов Штормграда.','Чтобы призвать инкуба, нужен мощный реагент – символ дружбы и верности.\n\nЯ заглянул в прошлое сквозь туман времени и увидел небольшую статуэтку, которая годится для ритуала.\n\nТысячи лет назад она принадлежала двум друзьям. Они давно мертвы, но их реликвия сохранилась.\n\nИди по дороге в Ясеневый лес, потом сверни на запад и иди дальше мимо заставы Мейстры. Ищи дом между деревьев – статуэтка находится в нем.','','','','','',''),
(78307,'Рог Кселтоса','Журнал','Описание','','','','','',''),
(79362,'Щит Гранта','Найдите палицу Гранта у одного из скелетов на кладбище Вороньего Холма, а затем вернитесь к Шире Фон-Инди в Темнолесье за новой информацией.','Это щит, оставленный духом Гранта Вэлора, главы рода Вэлор и героя Вороньего Холма.\n\nДух Гранта все еще сражался с нежитью: возможно, его незавершенным делом на этой земле было покончить с воином Плети, который ранил его на кладбище Вороньего Холма. Скорее всего, палица павшего героя так и застряла в теле того чудища.','','','','','',''),
(86776,'Материалы для кузницы','Принесите $1oa |4бронзовый слиток:бронзовых слитка:бронзовых слитков; Морану Медношпунту.','Телсамар – прекрасное место для жизни, но всех удобств Стальгорна тут нет. У меня постоянно заканчивается бронза! Мне нужно больше бронзы для изготовления инструментов, котелков и чайников!\n\nЯ вижу, что у тебя есть опыт работы в кузнице. Как думаешь, сможешь выплавить для меня несколько бронзовых слитков? Я тебе хорошо заплачу!','','','','','',''),
(92706,'РАЗЫСКИВАЕТСЯ: Брууз','Принесите спинной плавник Брууза Газлоу в Кабестан.','Внимание всем рыболовам!\n\nВ водах около пристани завелась огромная акула, которая нападает на матросов и небольшие суда. Работники пристани дали ей прозвище "Брууз". Тот, кто принесет мне ее плавник, будет щедро вознагражден!\n\n– Газлоу','','','','','',''),
(92742,'Проверка колодцев','Используйте набор для взятия образцов колодезной воды у колодцев во владении Янсена и на ферме Мольсена.','Нужно отыскать источник яда, поразившего эти земли, и понять его природу. Начнем с исследования подземных вод под местными фермами.\n\nСтупай во владение Янсена на севере и на ферму Мольсена к северо-западу отсюда и возьми пробы из колодцев.','','','','','',''),
(92909,'Урожай жнецов','Озвин Железнозубчик на ферме Сальдена просит принести ему 14 изопружин голема и 5 гиростабилизаторов голема.','О нет... вот это я попал!\n\nМне рассказали, что в Западном крае на полях бесчинствуют големы, так что я прибыл сюда аж из самого Стальгорна, чтобы попробовать их перенастроить. Но они оказались куда агрессивнее, чем предсказывали мои расчеты. Даже загнали меня вот в эту конюшню!\n\nБудь у меня изопружины и гиростабилизаторы големов, я бы собрал устройство, которое поможет скрыться. Соберешь для меня запчасти?','','','','','',''),
(92911,'Урожай жнецов','Озвин Железнозубчик на ферме Сальдена просит принести ему 8 изопружин голема, 4 медных регулятора и кустарный прицел.','Понятно... Теперь я чуть лучше понимаю, как эти чудища работают. У меня есть идея, как можно обойти их системы – по крайней мере, временно.\n\nЯ продолжу ковыряться в том, что ты $gпринес:принесла;, а пока не $gмог:могла; бы ты собрать кое-какие детали для устройства?','','','','','',''),
(93963,'Знакомство с Альянсом','Получите дальнейшие указания у Рандала Эмерсона в крепости Штормграда, а затем найдите короля Магни Бронзоборода, главного механика Меггакрута и Тиранду Шелест Ветра и поговорите с ними.','В каждом из наших городов – Штормграде, Стальгорне и Дарнасе – обитают разные народы с уникальной культурой. Раз уж ты в гостях у Альянса здесь, на Азероте, выдели время для того, чтобы по очереди посетить каждую из наших столиц.\n\nДля начала поговори с Рандалом Эмерсоном в южном вестибюле – он укажет тебе дорогу.','','','','','',''),
(94231,'Задание мастера: лунная винтовка','Добудьте предметы из заказа и доставьте в место, отмеченное на карте. Чтобы получить плату, нужно иметь при себе это свидетельство.','<В записке, написанной выцветшими чернилами, содержится заказ на $2oa |4лунную винтовку:лунные винтовки:лунных винтовок;, а также сведения о том, куда все нужно доставить, и об оплате. Снизу указано, что этот заказ можно передавать другим.>','','','','','',''),
(94235,'Задание мастера: универсальный гномий пульт управления','Добудьте предметы из заказа и доставьте в место, отмеченное на карте. Чтобы получить плату, нужно иметь при себе это свидетельство.','<В записке, написанной выцветшими чернилами, содержится заказ на $2oa |4универсальный гномий пульт управления:универсальных гномих пульта управления:универсальных гномих пультов управления;, а также сведения о том, куда все нужно доставить, и об оплате. Снизу указано, что этот заказ можно передавать другим.>','','','','','',''),
(94239,'Задание мастера: тонкие кожаные штаны','Добудьте предметы из заказа и доставьте в место, отмеченное на карте. Чтобы получить плату, нужно иметь при себе это свидетельство.','<В записке, написанной выцветшими чернилами, содержится заказ на $2oa |4пару:пары:пар; тонких кожаных штанов, а также сведения о том, куда все нужно доставить, и об оплате. Снизу указано, что этот заказ можно передавать другим.>','','','','','',''),
(94255,'Задание мастера: туфли из паутины','Добудьте предметы из заказа и доставьте в место, отмеченное на карте. Чтобы получить плату, нужно иметь при себе это свидетельство.','<В записке, написанной выцветшими чернилами, содержится заказ на $2oa |4пару:пары:пар; туфель из паутины, а также сведения о том, куда все нужно доставить, и об оплате. Снизу указано, что этот заказ можно передавать другим.>','','','','','',''),
(94465,'Зов Огня','Отнесите факел Дремлющего Пламени Бралдиру Пеплоплащу в Лок Модане.','Да уж, у тебя есть сила носить тотем огня – но это еще не значит, что ты $gготов:готова;.\n\nЗа долиной Королей, среди утесов Лок Модана лежит тайная тропа к одной из наших священных вершин. Там Бралдир Пеплоплащ стережет святилище Дремлющего Пламени. \n\nОтнеси ему этот факел, и он поймет, зачем ты $gпришел:пришла;. Если вернешься с факелом, зажженным от жаровни святилища, я обучу тебя всему, что нужно для владения тотемом огня.','','','','','',''),
(94494,'Зов Воды','Найдите Норрика Тана Лока в Лок Модане.','Много воды утекло со времени последнего испытания, $n. Ты $gпроявил:проявила; немало упорства в учении, но теперь тебе пришло время узнать о чистоте воды.\n\nОтыщи Норрика Тана Лока. Он живет у северо-западного края озера, к югу от Каменной Плотины. Там и найдешь его землянку. Удачи тебе, $n.','','','','','',''),
(94500,'Зов Воды','Наполните пустой синий бурдюк для воды в водах Астранаара в Ясеневом лесу и отнесите воду Гервдане Саэгрунд в Болотину.','Возьми этот бурдюк и отправляйся прямиком в изумрудные чащи Ясеневого леса. Среди вод, не затронутых порчей, ты найдешь деревушку Астранаар. На дне тамошнего озера лежат руины зданий, помнящих давние времена. Принеси мне образец той воды – чистой, древней и, возможно, зачарованной.\n\nЭто последнее, что мне нужно, прежде чем я отправлю тебя к Норрику.\n\nСядь на корабль в Гавани Менетилов, идущий в Аубердин. Он останавливается в Южнобережье.\n\nИ имей в виду... у леса есть глаза, и они никогда не моргают.','','','','','',''),
(95161,'Помни, что я люблю тебя','Принесите запятнанное кровью письмо Аветте Хвористинке в Сумеречный лес.','Если ты ищешь Джереми Хартвивера, то обратись к его новоиспеченной приемной матери. Ее зовут Аветта Хвористинка, и живет она в Сумеречном лесу. Добрейшая женщина. Ей, должно быть, понадобился помощник по хозяйству, но это лучше, чем жить в приюте.\n\nЕсли увидишься с Джереми, передай ему, что мы все про него вспоминаем, хорошо?','','','','','',''),
(97253,'Запчасти и детали','Соберите $1oa |4горсть:горсти:горстей; изощренных деталей в верхнем лагере пиратов к югу от Кабестана, а затем вернитесь к Рениксу Презренному в Кабестан.','Эй, на минутку.\n\nКороче говоря, у нас проблема с пиратами. Кого я только ни посылал с ними разобраться – никто не вернулся назад. Тогда я подумал: а если послать машину? Оказалось, ятаганы раскручивают запчасти не сильно хуже отверток. Не успел я направить машину домой, как она превратилась в кучу железок и разлетелась по всему их лагерю!\n\nМне нужно вернуть детали. Причем это всего лишь коротенькая вылазка за трофеями, так что твои шансы на выживание наверняка НАМНОГО выше, чем в предыдущие разы. Ну че?','','','','','',''),
(97944,'Основы походной жизни: травничество','Поговорите с Малорном Остролистом в Доланааре, чтобы показать свои навыки и научиться создавать предмет для лагеря, соответствующий вашей профессии.','Ты, похоже, уже многое знаешь о травничестве. Собирать цветы – не просто развлечение. Это занятие может быть полезным... и весьма прибыльным.\n\nСдается мне, я знаю кое-кого, кто может научить тебя создавать ароматную свечу для лагеря. Чтобы целители и заклинатели достойно показывали себя в бою, им нужно правильное состояние духа, и ароматические свечи в этом здорово помогают. Все знакомые заклинатели будут тебе благодарны.','Отыщите лагерь охотников','','','','',''),
(97949,'Основы походной жизни: снятие шкур','Поговорите с Раднаалом Гривопрядом на дороге из Доланаара в Дарнас, чтобы показать свои навыки и научиться создавать предмет для лагеря, соответствующий вашей профессии.','Умение быстро снимать с убитых зверей кожи и шкуры – один из наиболее полезных навыков для любого искателя приключений.\n\nСдается мне, я знаю кое-кого, кто может научить тебя создавать удобный стул для лагеря. Иногда очень важно, чтобы было где расслабиться, – а из шкур, которые ты добываешь, можно скроить очень удобное сиденье. Благодаря этому ты точно будешь в форме, когда придет время для следующей потасовки.','Отыщите лагерь охотников','','','','',''),
(98027,'Сияющее ожерелье с полумесяцем','Отнесите ожерелье с полумесяцем Майлинн в Астранаар.','<Серебряное ожерелье тускло поблескивает у вас в руках. Оно сделано в форме лунного серпа, напоминающего другие встречавшиеся вам символы ночных эльфов.\n\nПеревернув ожерелье, вы видите гравировку: "Алор''лорма, Майлинн". Возможно, оно принадлежит Майлинн из Астранаара?>','','','','','',''),
(98071,'Промысел пивовара','Отнесите бутылки с фолрукским сортовым вином в Дун Гарок в юго-восточной части предгорий Хилсбрада и принесите назад мешок их домашнего хмеля.','Я немножко торгую с коллегами в Дун Гароке. Похоже, не только мы скучаем по виноградникам семьи Фолрук! Большую часть готового вина лучших годов уже выпили, но у нас еще есть несколько ящиков в погребах.\n\nОтнеси этот ящик фолрукского сортового в Дун Гарок на юго-востоке и оставь у их очага на месте сбора, что у подножия крепости.\n\nВзамен принеси назад мешок домашнего хмеля.\n\nЭта крепость – самое похожее на дом место в этих землях!','','','','','',''),
(98209,'Небесный цветок','Отнесите Норд''эль Тандрису Ветропряду в Аубердин на Темных берегах.\n\nКажется, Силесса упоминала, что туда можно добраться на корабле из Гавани Менетилов.','Не $gмог:могла; бы ты отнести Норд''эль старейшине Тандрису Ветропряду в Аубердин?\n\nОтсюда ты быстро сможешь добраться туда на корабле.\n\nПрости, что приходится тебя просить. Я еще не восстановила силы после тягот путешествия – и бегства от тех несносных мурлоков, накинувшихся на меня, когда я попыталась заполучить священный цветок.','','','','','',''),
(98216,'Понимание настоящего','Используйте камень Гоаз вблизи хранителя Гоаз и принесите его ключ-камень титанов геологу Вельгару.','Древние боги?! Это точно не к добру!\n\nЯ разобрал на камне отрывок текста, в котором говорится о каком-то хранителе. О чем бы там ни шла речь, это должно быть как-то связано с камнем!\n\nВозьми его с собой и поищи в зоне раскопок какой-нибудь большой объект, созданный титанами. Прочитай последний отрывок текста на камне и посмотри, что произойдет!\n\nЕсли я прав, то ты активируешь найденную штуку. Если так и случится, разберись с ней, но постарайся не повредить другие возможные находки! Нам просто необходимо узнать больше!','','','','','',''),
(98223,'Старые привычки','Отнесите изодранную книгу заклинаний капитану Крепкому Кулаку в Гавань Менетилов.','Эту сильно обгоревшую книгу, возможно, опалил тот же драконий огонь, что уничтожил немало орков из клана Драконьей Пасти.\n\nТо немногое, что удается прочитать, кажется, описывает ритуалы, связанные с Душой Демона, которую клан использовал для порабощения драконов.\n\nЗаписи слишком обрывочные, чтобы быть действительно полезными, но, судя по грубо вставленным страницам из кожи, Нек''рош пытался восстановить книгу. В строках, не так давно нанесенных свежими чернилами, упоминается некий "Совет Теней".\n\nКапитан Крепкий Кулак в Гавани Менетилов наверняка захочет об этом узнать.','','','','','',''),
(98291,'Гибель Драконьей Пасти!','Убейте $1oa |4завоевателя:завоевателей:завоевателей;, $2oa |4душеплета:душеплетов:душеплетов; и $3oa |4лазутчика:лазутчиков:лазутчиков; из клана Драконьей Пасти в Убежище Драконьей Пасти для Ховина Мягкое Перо.','Я собираюсь вернуться в Грим Батол и отвоевать его для клана Громового Молота, $n. Или хотя бы разузнать побольше.\n\nНе надо на меня так таращиться. Я понимаю риски и не собираюсь просто так размахивать молотом, знаешь ли.\n\nВ любом случае сначала мне понадобится твоя помощь. Орки Драконьей Пасти уже наступают. Они повсюду в Убежище Драконьей Пасти, где красные драконы их когда-то разбили.\n\nМне нужно, чтобы ты $gпроредил:проредила; их ряды. Так у меня появится хоть какой-то шанс подобраться поближе. Если пойдешь по дороге на восток, то непременно с ними встретишься.','','','','','',''),
(98297,'Остановка цикла','Убейте подчиненного драконоида у врат Драконьей Пасти по просьбе Ховина Мягкое Перо.','Пока тебя не было, я совершил короткий пробный полет. Есть хорошая новость: броня, которую мы с тобой изготовили для Глухоклюв, просто бесподобна!\n\nНо есть и плохая: я видел, как орки Драконьей Пасти подчинили красного драконоида.\n\nНу уж нет, снова им такого позволить нельзя.\n\nТебе надо его уничтожить. Без помощи друзей тут, ясное дело, никак не обойтись. Сначала убей чернокнижников, которые удерживают дракона, а затем избавь его от мучений.\n\nМы не позволим никому преградить путь Громовому Молоту.','','','','','',''),
(98326,'Ледяной Вой','Убейте Ледяного Воя и верните мешок рыбы Гретте Гантер в поселке Пивоваров.','Ты хоть знаешь, как трудно рыбачить на замерзшем озере? Мой бедный муж Пакстон уже несколько дней там торчит, а улова едва наберется на один мешок.\n\nВернее, мешок у нас был, пока распроклятый вендиго не напал на меня и не стащил нашу рыбу. У нас недели уйдут на то, чтобы снова наловить рыбы! Если, конечно, этот горлопан Ледяной Вой не испортил весь клев.\n\nСделай одолжение и верни наш улов, ладно? Этот слюнявый громила скрывается где-то в глубине Серой берлоги на юго-востоке.','','','','','',''),
(98372,'Бесславная участь','','','','','','','',''),
(98815,'Шкуры нагорья','Отнесите $1oa |4шкуру:шкуры:шкур; чащобного ящера кожевнику Джеймсу Халлорану в Гавань Менетилов.','На нагорье есть какие-то руины, и сейчас там работает экспедиция – мечтают разгадать их загадки. А я вот знаю, что в тех горных болотах водятся звери и разнообразные твари, которые обитают только там. Как насчет того, чтобы сходить туда с хорошо снаряженными друзьями, а потом заключить со мной сделку?\n\nПринеси мне шкуры четырех чащобных ящеров, а я подберу для тебя нечто такое, чтобы дело того стоило. Они, возможно, будут прятаться, но ты их все равно найди.','','','','','','');
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`PortraitGiverText`,`PortraitGiverName`,`PortraitTurnInText`,`PortraitTurnInName`,`QuestCompletionLog`,`VerifiedBuild`) SELECT t.`ID`,'ruRU',t.`LogTitle`,t.`LogDescription`,t.`QuestDescription`,t.`AreaDescription`,t.`PortraitGiverText`,t.`PortraitGiverName`,t.`PortraitTurnInText`,t.`PortraitTurnInName`,t.`QuestCompletionLog`,70862 FROM `tmp_ruru_quest_template_locale` t JOIN `quest_template` b ON b.`ID`=t.`ID` LEFT JOIN `quest_template_locale` l ON l.`ID`=t.`ID` AND l.`locale`='ruRU' WHERE l.`ID` IS NULL;
