-- WoW Forever: Russian texts from one more Russian player's game cache folder (Cache\WDB\ruRU, build 70862, Blizzard's
-- live realm), sent to us on 2026-11-10 evening, read with tools/forever_cache. Only records no earlier Russian cache had and only text
-- with Russian letters are used. Existing Russian text is kept: only missing rows and empty fields are filled, and only for
-- quests, NPCs and objects our world has. Safe to run again.

-- A. Russian quest text for 130 quests.
DROP TEMPORARY TABLE IF EXISTS `tmp_ruru_quest_template_locale`;
CREATE TEMPORARY TABLE `tmp_ruru_quest_template_locale` (`ID` INT UNSIGNED NOT NULL, `LogTitle` MEDIUMTEXT, `LogDescription` MEDIUMTEXT, `QuestDescription` MEDIUMTEXT, `AreaDescription` MEDIUMTEXT, `PortraitGiverText` MEDIUMTEXT, `PortraitGiverName` MEDIUMTEXT, `PortraitTurnInText` MEDIUMTEXT, `PortraitTurnInName` MEDIUMTEXT, `QuestCompletionLog` MEDIUMTEXT, PRIMARY KEY (`ID`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
UPDATE `quest_template_locale` l JOIN `tmp_ruru_quest_template_locale` t ON t.`ID`=l.`ID` AND l.`locale`='ruRU' SET l.`LogTitle`=IF(COALESCE(l.`LogTitle`,'')='',t.`LogTitle`,l.`LogTitle`), l.`LogDescription`=IF(COALESCE(l.`LogDescription`,'')='',t.`LogDescription`,l.`LogDescription`), l.`QuestDescription`=IF(COALESCE(l.`QuestDescription`,'')='',t.`QuestDescription`,l.`QuestDescription`), l.`AreaDescription`=IF(COALESCE(l.`AreaDescription`,'')='',t.`AreaDescription`,l.`AreaDescription`), l.`PortraitGiverText`=IF(COALESCE(l.`PortraitGiverText`,'')='',t.`PortraitGiverText`,l.`PortraitGiverText`), l.`PortraitGiverName`=IF(COALESCE(l.`PortraitGiverName`,'')='',t.`PortraitGiverName`,l.`PortraitGiverName`), l.`PortraitTurnInText`=IF(COALESCE(l.`PortraitTurnInText`,'')='',t.`PortraitTurnInText`,l.`PortraitTurnInText`), l.`PortraitTurnInName`=IF(COALESCE(l.`PortraitTurnInName`,'')='',t.`PortraitTurnInName`,l.`PortraitTurnInName`), l.`QuestCompletionLog`=IF(COALESCE(l.`QuestCompletionLog`,'')='',t.`QuestCompletionLog`,l.`QuestCompletionLog`);
DROP TEMPORARY TABLE `tmp_ruru_quest_template_locale`;

-- B. Russian NPC names and titles for 487 NPCs.
DROP TEMPORARY TABLE IF EXISTS `tmp_ruru_creature_template_locale`;
CREATE TEMPORARY TABLE `tmp_ruru_creature_template_locale` (`entry` INT UNSIGNED NOT NULL, `Name` MEDIUMTEXT, `NameAlt` MEDIUMTEXT, `Title` MEDIUMTEXT, `TitleAlt` MEDIUMTEXT, PRIMARY KEY (`entry`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
UPDATE `creature_template_locale` l JOIN `tmp_ruru_creature_template_locale` t ON t.`entry`=l.`entry` AND l.`locale`='ruRU' SET l.`Name`=IF(COALESCE(l.`Name`,'')='',t.`Name`,l.`Name`), l.`NameAlt`=IF(COALESCE(l.`NameAlt`,'')='',t.`NameAlt`,l.`NameAlt`), l.`Title`=IF(COALESCE(l.`Title`,'')='',t.`Title`,l.`Title`), l.`TitleAlt`=IF(COALESCE(l.`TitleAlt`,'')='',t.`TitleAlt`,l.`TitleAlt`);
DROP TEMPORARY TABLE `tmp_ruru_creature_template_locale`;

-- C. Russian object names for 337 objects.
DROP TEMPORARY TABLE IF EXISTS `tmp_ruru_gameobject_template_locale`;
CREATE TEMPORARY TABLE `tmp_ruru_gameobject_template_locale` (`entry` INT UNSIGNED NOT NULL, `name` MEDIUMTEXT, `castBarCaption` MEDIUMTEXT, `unk1` MEDIUMTEXT, PRIMARY KEY (`entry`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
UPDATE `gameobject_template_locale` l JOIN `tmp_ruru_gameobject_template_locale` t ON t.`entry`=l.`entry` AND l.`locale`='ruRU' SET l.`name`=IF(COALESCE(l.`name`,'')='',t.`name`,l.`name`), l.`castBarCaption`=IF(COALESCE(l.`castBarCaption`,'')='',t.`castBarCaption`,l.`castBarCaption`), l.`unk1`=IF(COALESCE(l.`unk1`,'')='',t.`unk1`,l.`unk1`);
DROP TEMPORARY TABLE `tmp_ruru_gameobject_template_locale`;
